<?php require __DIR__.'/auth.php';guard();require_once dirname(__DIR__).'/config.php';header('Content-Type:text/csv');header('Content-Disposition:attachment;filename="cavibe-survey.csv"');$o=fopen('php://output','w');fputcsv($o,['ID','Name','Email','Phone','School','Level','Tester','Submitted','Extended Answers']);foreach($pdo->query("SELECT * FROM student_survey_responses ORDER BY created_at DESC") as $r){$s=$pdo->prepare("SELECT question_key,answer_json FROM student_survey_answers WHERE response_public_id=?");$s->execute([$r['public_id']]);$a=[];foreach($s as $x)$a[$x['question_key']]=json_decode($x['answer_json'],true);fputcsv($o,[$r['public_id'],$r['full_name'],$r['email'],$r['phone'],$r['school'],$r['student_level'],$r['willing_to_test'],$r['created_at'],json_encode($a,JSON_UNESCAPED_UNICODE)]);}